15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(sharesHousehold)) {
20	            return;
21	        }
22	        String householdId = owner.getHouseholdId();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
26	            }
27	        }
28	    }
